function tio(val, src)
    if no["oxydPart"].state == ON then
        if src == no["scaleI"] then
            if val == true then
                no["bridgeI"]:close()
            else
                no["bridgeI"]:open()
            end
        end
        if src == no["scaleJ"] then
            if val == true then
                no["bridgeJ"]:close()
            else
                no["bridgeJ"]:open()
            end
        end
    end
    if no["mediPart"].state == ON then
        if src == no["scaleI"] then
            if val == false then
                no["doorR"]:close()
            else
                no["doorR"]:open()
            end
        end
        if src == no["scaleJ"] then
            if val == false then
                no["doorS"]:close()
            else
                no["doorS"]:open()
            end
        end
    end
end

